// writeError writes an HTTP response with a valid Twirp error format, and triggers hooks.
// If err is not a twirp.Error, it will get wrapped with twirp.InternalErrorWith(err)
func (s *parsecServiceServer) writeError(ctx context.Context, resp http.ResponseWriter, err error) {
	writeError(ctx, resp, err, s.hooks)
}

// handleRequestBodyError is used to handle error when the twirp server cannot read request
func (s *parsecServiceServer) handleRequestBodyError(ctx context.Context, resp http.ResponseWriter, msg string, err error) {
	if context.Canceled == ctx.Err() {
		s.writeError(ctx, resp, twirp.NewError(twirp.Canceled, "failed to read request: context canceled"))
		return
	}
	if context.DeadlineExceeded == ctx.Err() {
		s.writeError(ctx, resp, twirp.NewError(twirp.DeadlineExceeded, "failed to read request: deadline exceeded"))
		return
	}
	s.writeError(ctx, resp, twirp.WrapError(malformedRequestError(msg), err))
}

// ParsecServicePathPrefix is a convenience constant that may identify URL paths.
// Should be used with caution, it only matches routes generated by Twirp Go clients,
// with the default "/twirp" prefix and default CamelCase service and method names.
// More info: https://twitchtv.github.io/twirp/docs/routing.html
const ParsecServicePathPrefix = "/twirp/parsec.ParsecService/"

func (s *parsecServiceServer) ServeHTTP(resp http.ResponseWriter, req *http.Request) {
	ctx := req.Context()
	ctx = ctxsetters.WithPackageName(ctx, "parsec")
	ctx = ctxsetters.WithServiceName(ctx, "ParsecService")
	ctx = ctxsetters.WithResponseWriter(ctx, resp)

	var err error
	ctx, err = callRequestReceived(ctx, s.hooks)
	if err != nil {
		s.writeError(ctx, resp, err)
		return
	}

	if req.Method != "POST" {
		msg := fmt.Sprintf("unsupported method %q (only POST is allowed)", req.Method)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}

	// Verify path format: [<prefix>]/<package>.<Service>/<Method>
	prefix, pkgService, method := parseTwirpPath(req.URL.Path)
	if pkgService != "parsec.ParsecService" {
		msg := fmt.Sprintf("no handler for path %q", req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}
	if prefix != s.pathPrefix {
		msg := fmt.Sprintf("invalid path prefix %q, expected %q, on path %q", prefix, s.pathPrefix, req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}

	switch method {
	case "Manifest":
		s.serveManifest(ctx, resp, req)
		return
	case "OpenPublic":
		s.serveOpenPublic(ctx, resp, req)
		return
	case "CreatePrivate":
		s.serveCreatePrivate(ctx, resp, req)
		return
	case "ListChannels":
		s.serveListChannels(ctx, resp, req)
		return
	case "GetChannel":
		s.serveGetChannel(ctx, resp, req)
		return
	case "DeleteChannel":
		s.serveDeleteChannel(ctx, resp, req)
		return
	case "Publish":
		s.servePublish(ctx, resp, req)
		return
	case "Presence":
		s.servePresence(ctx, resp, req)
		return
	case "RefreshToken":
		s.serveRefreshToken(ctx, resp, req)
		return
	case "IssueMgmt":
		s.serveIssueMgmt(ctx, resp, req)
		return
	case "ListKeys":
		s.serveListKeys(ctx, resp, req)
		return
	case "GenerateKey":
		s.serveGenerateKey(ctx, resp, req)
		return
	case "PromoteKey":
		s.servePromoteKey(ctx, resp, req)
		return
	case "RetireKey":
		s.serveRetireKey(ctx, resp, req)
		return
	case "ReloadKeys":
		s.serveReloadKeys(ctx, resp, req)
		return
	case "DlqList":
		s.serveDlqList(ctx, resp, req)
		return
	case "DlqCount":
		s.serveDlqCount(ctx, resp, req)
		return
	case "DlqDiscard":
		s.serveDlqDiscard(ctx, resp, req)
		return
	case "DlqReplay":
		s.serveDlqReplay(ctx, resp, req)
		return
	default:
		msg := fmt.Sprintf("no handler for path %q", req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}
}

